        LinearLayout amountRow=row();LinearLayout.LayoutParams ar=new LinearLayout.LayoutParams(-1,-2);ar.topMargin=dp(8);hero.addView(amountRow,ar);amountRow.addView(text(money.format(monthlyTotal()),36,heroText(),true));
        LinearLayout stats=row();LinearLayout.LayoutParams stp=new LinearLayout.LayoutParams(-1,-2);stp.topMargin=dp(10);hero.addView(stats,stp);stats.addView(text("半年付/年付按周期折算",12,heroSubtle(),false));View stsp=new View(this);stats.addView(stsp,new LinearLayout.LayoutParams(0,1,1));stats.addView(text(items.size()+" 项订阅",12,heroSubtle(),false));

        LinearLayout section=column();pad(section,22,0,22,0);feed.addView(section);section.addView(text("即将扣费",19,BLACK,true));TextView sub=text("未来 7 天",13,GRAY,false);LinearLayout.LayoutParams subp=new LinearLayout.LayoutParams(-2,-2);subp.topMargin=dp(4);section.addView(sub,subp);
        ArrayList<Sub> upcoming=new ArrayList<>();for(Sub s:items){long d=ChronoUnit.DAYS.between(today,nextDue(s,today));if(d>=0&&d<=7)upcoming.add(s);}upcoming.sort(Comparator.comparing(s->nextDue(s,today)));
        if(upcoming.isEmpty()){
            LinearLayout emptyDue=row();emptyDue.setBackground(bg(SURFACE,16));pad(emptyDue,16,14,16,14);LinearLayout.LayoutParams edp=new LinearLayout.LayoutParams(-1,-2);edp.topMargin=dp(14);section.addView(emptyDue,edp);TextView check=text("✓",18,0xff00a870,true);check.setGravity(Gravity.CENTER);check.setBackground(bg(0xffe4f7ef,50));emptyDue.addView(check,new LinearLayout.LayoutParams(dp(38),dp(38)));LinearLayout msg=column();LinearLayout.LayoutParams mp=new LinearLayout.LayoutParams(0,-2,1);mp.leftMargin=dp(12);emptyDue.addView(msg,mp);msg.addView(text("近期没有扣费",14,BLACK,true));msg.addView(text("到期前的订阅会显示在这里",12,GRAY,false));
        }else for(Sub s:upcoming)addDueCard(s,nextDue(s,today),today,section);

        LinearLayout listHead=row();LinearLayout.LayoutParams lhp=new LinearLayout.LayoutParams(-1,-2);lhp.topMargin=dp(28);section.addView(listHead,lhp);listHead.addView(text("我的订阅",19,BLACK,true));View flex=new View(this);listHead.addView(flex,new LinearLayout.LayoutParams(0,1,1));TextView count=text(items.size()+" 项",13,GRAY,false);listHead.addView(count);
